import React, { useState } from "react";
import { Text, View } from "react-native";
import { TemplateShell, SectionHeading } from "./template-shell";
import { useSkeuo } from "../theme";
import { SkeuoTimer } from "../skeuo-timer";
import { SkeuoCard } from "../skeuo-card";
import { SkeuoInput } from "../skeuo-input";
import { SkeuoSwitch } from "../skeuo-switch";
import { HabitList } from "../blocks/habit-list";
import { ActivityChart } from "../blocks/activity-chart";
const items = [
  { value: "focus", label: "Focus" },
  { value: "habits", label: "Habits" },
  { value: "journal", label: "Journal" },
  { value: "settings", label: "Settings" },
];
export function StillTemplate() {
  const { colors: c } = useSkeuo();
  const [tab, setTab] = useState("focus");
  const [note, setNote] = useState("");
  const [gentle, setGentle] = useState(true);
  const [done,setDone] = useState(["A little movement"]);
  return (
    <TemplateShell
      name="still"
      subtitle="LESS RUSH. MORE ROOM."
      items={items}
      value={tab}
      onValueChange={setTab}
      variant="keys"
    >
      <View style={{display:tab === "focus" ? "flex" : "none",gap:24}}>
          <SectionHeading
            title="Just this one thing."
            detail="Give your attention somewhere to settle."
          />
          <SkeuoCard style={{ paddingVertical: 30 }}>
            <SkeuoTimer />
          </SkeuoCard>
          <Text style={{ color: c.muted, fontSize: 12, lineHeight: 20 }}>
            Put your phone down. Pick up where you left off.
          </Text>
          <Text style={{ color: c.ink, fontSize: 16, fontWeight: "600" }}>
            Small steps, today
          </Text>
          <HabitList value={done} onValueChange={setDone}/>
      </View>
      {tab === "focus" ? null : tab === "habits" ? (
        <>
          <SectionHeading
            title="A little, every day."
            detail="Progress without the pressure."
          />
          <SkeuoCard>
            <HabitList value={done} onValueChange={setDone}/>
          </SkeuoCard>
          <SkeuoCard>
            <Text style={{ color: c.ink }}>Your week, so far</Text>
            <ActivityChart />
          </SkeuoCard>
        </>
      ) : tab === "journal" ? (
        <>
          <SectionHeading
            title="Leave a thought here."
            detail="It doesn't need to be a big one."
          />
          <SkeuoInput
            label="Today's note"
            placeholder="What made today feel different?"
            multiline
            numberOfLines={8}
            value={note}
            onChangeText={setNote}
          />
          <Text style={{ color: c.muted, fontSize: 12 }}>
            Private to this demo session. Nothing is uploaded.
          </Text>
        </>
      ) : (
        <>
          <SectionHeading title="At your own pace." />
          <SkeuoCard>
            <SkeuoSwitch
              label="Gentle reminders"
              checked={gentle}
              onCheckedChange={setGentle}
            />
            <Text style={{ color: c.muted, lineHeight: 20 }}>
              A sample preference. This template does not schedule system
              notifications.
            </Text>
          </SkeuoCard>
        </>
      )}
    </TemplateShell>
  );
}

import React from "react";
import { ScrollView, Text, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useSkeuo } from "../theme";
import {
  SkeuoBottomBar,
  type BottomBarItem,
  type BottomBarVariant,
} from "../skeuo-bottom-bar";
export function TemplateShell({
  name,
  subtitle,
  children,
  items,
  value,
  onValueChange,
  variant = "dock",
  action,
}: {
  name: string;
  subtitle?: string;
  children: React.ReactNode;
  items: BottomBarItem[];
  value: string;
  onValueChange: (value: string) => void;
  variant?: BottomBarVariant;
  action?: React.ReactNode;
}) {
  const { colors: c } = useSkeuo();
  const insets = useSafeAreaInsets();
  return (
    <View
      style={{ flex: 1, backgroundColor: c.background, paddingTop: insets.top }}
    >
      <View
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          paddingHorizontal: 22,
          paddingTop: subtitle ? 18 : 12,
          paddingBottom: subtitle ? 18 : 16,
        }}
      >
        <View style={{ gap: 3 }}>
          <Text
            style={{
              color: c.ink,
              fontSize: 20,
              fontWeight: "700",
              letterSpacing: -0.6,
            }}
          >
            {name}
            <Text style={{ color: c.accent }}>.</Text>
          </Text>
          {subtitle && (
            <Text style={{ color: c.muted, fontSize: 10 }}>{subtitle}</Text>
          )}
        </View>
        {action ?? (
          <View
            style={{
              height: 34,
              width: 34,
              borderRadius: 17,
              backgroundColor: c.well,
              borderWidth: 1,
              borderColor: c.edge,
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Text style={{ color: c.muted, fontSize: 11 }}>AM</Text>
          </View>
        )}
      </View>
      <ScrollView
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{
          paddingHorizontal: 22,
          paddingBottom: 24,
          gap: subtitle ? 24 : 18,
        }}
      >
        {children}
      </ScrollView>
      <SkeuoBottomBar
        items={items}
        value={value}
        onValueChange={onValueChange}
        variant={variant}
        bottomInset={insets.bottom}
      />
    </View>
  );
}
export function SectionHeading({
  title,
  detail,
}: {
  title: string;
  detail?: string;
}) {
  const { colors: c } = useSkeuo();
  return (
    <View style={{ gap: 7 }}>
      <Text
        accessibilityRole="header"
        style={{
          fontSize: 29,
          fontWeight: "500",
          color: c.ink,
          letterSpacing: -1,
        }}
      >
        {title}
      </Text>
      {detail && (
        <Text style={{ color: c.muted, fontSize: 13, lineHeight: 20 }}>
          {detail}
        </Text>
      )}
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import React from "react";
import { Pressable, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { useFeedback, useSkeuo } from "./theme";
import { SkeuoGlyph } from "./icons";
import { SkeuoDockBar, type DockBarProps } from "./skeuo-dock-bar";

export type { BottomBarItem } from "./skeuo-dock-bar";
export type BottomBarVariant = "dock" | "keys" | "rail" | "pill";
export function SkeuoBottomBar({
  items,
  value,
  onValueChange,
  variant = "dock",
  bottomInset = 0,
}: DockBarProps & { variant?: BottomBarVariant }) {
  if (variant === "dock") {
    return <SkeuoDockBar {...{ items, value, onValueChange, bottomInset }} />;
  }
  return <LabeledBottomBar {...{ items, value, onValueChange, variant, bottomInset }} />;
}

function LabeledBottomBar({
  items,
  value,
  onValueChange,
  variant,
  bottomInset = 0,
}: DockBarProps & { variant: Exclude<BottomBarVariant, "dock"> }) {
  const { colors: c } = useSkeuo();
  const feedback = useFeedback();
  return (
    <View
      accessibilityRole="tablist"
      accessibilityLabel="Bottom navigation"
      style={{
        paddingBottom: Math.max(8, bottomInset),
        paddingTop: 12,
        paddingHorizontal: variant === "rail" ? 0 : 12,
        backgroundColor: c.background,
      }}
    >
      <View
        style={{
          flexDirection: "row",
          gap: variant === "keys" ? 8 : 2,
          padding: variant === "pill" ? 5 : 0,
          borderWidth: variant === "pill" ? 1 : 0,
          borderColor: c.edge,
          borderRadius: variant === "pill" ? 32 : 16,
          backgroundColor: variant === "keys" ? c.background : c.well,
        }}
      >
        {items.map((item) => {
          const active = item.value === value;
          return (
            <Pressable
              key={item.value}
              accessibilityRole="tab"
              aria-selected={active}
              aria-disabled={!!item.disabled}
              accessibilityLabel={item.label}
              accessibilityState={{
                selected: active,
                disabled: !!item.disabled,
              }}
              disabled={item.disabled}
              onPress={() => {
                feedback();
                onValueChange(item.value);
              }}
              style={({ pressed }) => ({
                flex: 1,
                minHeight: 60,
                borderRadius: variant === "pill" ? 26 : 10,
                borderWidth: variant === "keys" ? 1 : 0,
                borderBottomWidth:
                  variant === "keys"
                    ? pressed
                      ? 1
                      : 4
                    : active && variant === "rail"
                      ? 3
                      : 1,
                borderColor: active && variant === "rail" ? c.accent : c.edge,
                backgroundColor: active
                  ? c.raised
                  : variant === "keys"
                    ? c.surface
                    : "transparent",
                opacity: item.disabled ? 0.4 : 1,
                transform: [{ translateY: pressed ? 2 : 0 }],
                overflow: "hidden",
              })}
            >
              <LinearGradient
                colors={active ? [c.raised, c.surface] : [c.well, c.well]}
                style={{
                  flex: 1,
                  alignItems: "center",
                  justifyContent: "center",
                  paddingVertical: 8,
                  gap: 3,
                }}
              >
                {item.icon ?? (
                  <SkeuoGlyph
                    name={item.value}
                    color={active ? c.accent : c.muted}
                  />
                )}
                <Text
                  numberOfLines={1}
                  style={{
                    fontSize: 10,
                    fontWeight: active ? "700" : "500",
                    color: active ? c.ink : c.muted,
                  }}
                >
                  {item.label}
                </Text>
              </LinearGradient>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

import { Text } from "react-native";
/** Simple line symbols keep the portable controls independent of an icon package. Hosts may pass their own icons. */
export function SkeuoGlyph({
  name,
  color = "#686863",
  size = 21,
}: {
