    focus: "◷",
    habits: "✓",
    journal: "≡",
    settings: "⚙",
    activity: "↗",
    goals: "◎",
    saved: "▱",
    add: "+",
    arrow: "↗",
    back: "‹",
    next: "›",
    play: "▶",
    pause: "Ⅱ",
    sound: "♪",
